  'The Finance hub is your money command center — invoices, receipts, collections, statements and accounts all reconcile into one set of KPIs.': 'ফাইনান্স হাব হলো আপনার অর্থের কমান্ড সেন্টার — ইনভয়েস, রিসিট, আদায়, স্টেটমেন্ট এবং অ্যাকাউন্ট — সব মিলে একটি KPI সেটে হিসাব মিলে যায়।',
  'The Overview hub is your control room. Sidebar hubs on the left, live KPIs on top, the AI Caretaker and your latest alerts below.': 'ওভারভিউ হাব হলো আপনার কন্ট্রোল রুম। বামে সাইডবার হাব, উপরে লাইভ KPI এবং নিচে AI কেয়ারটেকার ও আপনার সাম্প্রতিক অ্যালার্ট।',
  'The browser must be running for web push. Re-open the app and check Settings → Browser notifications still shows your device. If the browser permission was revoked, re-enable it and subscribe again. Old dead subscriptions are cleaned automatically.': 'ওয়েব পুশের জন্য ব্রাউজার চালু থাকতে হবে। অ্যাপটি আবার খুলুন এবং দেখুন সেটিংস → ব্রাউজার নোটিফিকেশনে আপনার ডিভাইসটি এখনও আছে কিনা। ব্রাউজার পারমিশন প্রত্যাহার করা হলে তা আবার সক্রিয় করে পুনরায় সাবস্ক্রাইব করুন। পুরনো মৃত সাবস্ক্রিপশনগুলো স্বয়ংক্রিয়ভাবে পরিষ্কার হয়ে যায়।',
