  'Lock name is required.': 'লকের নাম আবশ্যক।',
  'Technician is required.': 'টেকনিশিয়ান আবশ্যক।',
  'Liters must be positive.': 'লিটার ধনাত্মক হতে হবে।',
  'Open voting for "{title}"? Members can now cast votes.': '"{title}" এর জন্য ভোট খোলবেন? সদস্যরা এখন ভোট দিতে পারবেন।',
  'Close voting for "{title}"? Winners will be assigned committee roles.': '"{title}" এর জন্য ভোট বন্ধ করবেন? বিজয়ীরা কমিটির দায়িত্ব পাবেন।',
  'Delete election "{title}"? This cannot be undone.': '"{title}" নির্বাচন মুছে ফেলবেন? এটি ফেরানো যাবে না।',
  "1) POST app-login with { \"email\": \"...\", \"password\": \"***\" }.\n2) On success you get { \"ok\": true, \"token\": \"***\", \"user\": { ... } }.\n3) Send that token on every later call in the Authorization header, formatted as the word Bearer, a space, then your session token.\n\nAccounts are role-based: subscribers (kind=sub) and staff (kind=staff). A 2FA-protected superadmin login is two-step: the first POST returns { \"need_2fa\": true, \"method\": \"totp\" | \"email\" } with a 401; send the code back as { \"2fa_code\": \"...\" } (or add \"2fa_alt\": \"email\" to get an emailed code instead).\n\nPOST app-me returns the current user profile, plan catalog and subscription. POST app-logout revokes the token. Sessions expire after the configured TTL (default 7 days; superadmin 12h) — on a 401, re-login and refresh the token. POST app-sessions lists active sessions and supports revoke / revoke_others / revoke_all (pass an empty action {} to just list).": "1) { \"email\": \"...\", \"password\": \"***\" } সহ POST app-login করুন।\n2) সফল হলে পাবেন { \"ok\": true, \"token\": \"***\", \"user\": { ... } }।\n3) পরবর্তী প্রতিটি কলের Authorization হেডারে সেই টোকেন পাঠান — Bearer শব্দ, একটি স্পেস, তারপর আপনার সেশন টোকেন।\n\nঅ্যাকাউন্টগুলো রোল-ভিত্তিক: সাবস্ক্রাইবার (kind=sub) এবং স্টাফ (kind=staff)। 2FA-সুরক্ষিত সুপারঅ্যাডমিন লগইন দুই-ধাপের: প্রথম POST 401 সহ { \"need_2fa\": true, \"method\": \"totp\" | \"email\" } ফেরত দেয়; কোডটি { \"2fa_code\": \"...\" } হিসেবে পাঠান (অথবা ইমেইলে কোড পেতে \"2fa_alt\": \"email\" যোগ করুন)।\n\nPOST app-me বর্তমান ব্যবহারকারীর প্রোফাইল, প্ল্যান ক্যাটালগ ও সাবস্ক্রিপশন ফেরত দেয়। POST app-logout টোকেন বাতিল করে। কনফিগার করা TTL-এর পর সেশন শেষ হয় (ডিফল্ট ৭ দিন; সুপারঅ্যাডমিন ১২ঘণ্টা) — 401 পেলে আবার লগইন করে টোকেন রিফ্রেশ করুন। POST app-sessions সক্রিয় সেশন তালিকাভুক্ত করে এবং revoke / revoke_others / revoke_all সমর্থন করে (শুধু তালিকা পেতে খালি action {} পাঠান)।",
  "A complete integration that bills a tenant:\n\n1) Login — POST app-login { \"email\": \"owner@...\", \"password\": \"***\" } → { \"ok\": true, \"token\": \"***\" }\n2) Generate — POST app-invoice-auto { \"month\": \"2026-09\" }, passing the login token in the Authorization header\n3) List — POST app-bootstrap {} (or GET) to read the new invoice id/status\n4) Email — POST app-invoice-email { \"id\": \"INV-1043\" } (respect the 10/10-min limit)\n5) Payment — POST app-invoice-pay { \"id\": \"INV-1043\", \"amount\": 45000, \"method\": \"bKash\" } → invoice flips to Paid, receipt issued\n6) Verify — GET app-collections-summary → outstanding drops by the amount\n7) Statement — monthly, POST app-statement-email { \"month\": \"2026-09\", \"day\": 1 } with the service key (cron)\n\nEvery step returns { \"ok\": true } plus data; failures always carry a human-readable \"error\" string.": "একটি ভাড়াটিয়াকে বিল করার সম্পূর্ণ ইন্টিগ্রেশন:\n\n1) লগইন — POST app-login { \"email\": \"owner@...\", \"password\": \"***\" } → { \"ok\": true, \"token\": \"***\" }\n2) তৈরি — POST app-invoice-auto { \"month\": \"2026-09\" }, Authorization হেডারে লগইন টোকেন পাঠিয়ে\n3) তালিকা — নতুন ইনভয়েসের id/status পড়তে POST app-bootstrap {} (বা GET)\n4) ইমেইল — POST app-invoice-email { \"id\": \"INV-1043\" } (১০/১০-মিনিট লিমিট মানুন)\n5) পেমেন্ট — POST app-invoice-pay { \"id\": \"INV-1043\", \"amount\": 45000, \"method\": \"bKash\" } → ইনভয়েস Paid হয়, রসিদ ইস্যু হয়\n6) যাচাই — GET app-collections-summary → বকেয়া পরিমাণ কমে যায়\n7) স্টেটমেন্ট — মাসিক, সার্ভিস কী দিয়ে POST app-statement-email { \"month\": \"2026-09\", \"day\": 1 } (cron)\n\nপ্রতিটি ধাপ { \"ok\": true } সহ ডেটা ফেরত দেয়; ব্যর্থতা সবসময় মানব-পাঠযোগ্য \"error\" স্ট্রিং বহন করে।",
  "AI Caretaker (KR) 🤖": "এআই কেয়ারটেকার (KR) 🤖",
  "API overview & base URL": "এপিআই ওভারভিউ ও বেস ইউআরএল",
